package com.guidewire.fnol.orchestrator;
import com.guidewire.fnol.agents.*;import com.guidewire.fnol.common.Models.*;import com.guidewire.fnol.enrichment.*;import com.guidewire.fnol.guardrails.*;import org.springframework.stereotype.*;import java.util.*;
@Component public class FNOLOrchestrator {
  private final InputGuardrail input; private final OutputGuardrail output; private final PIIGuardrail piiGuard; private final ValidationGuardrail validation; private final VisionDamageAgent vision; private final PolicyValidatorAgent policy; private final ReserveCalculatorAgent reserve; private final PiiRedactionAgent pii; private final StatutoryDeadlineAgent deadline; private final SubrogationScorerAgent subro; private final AuditTrailAgent audit; private final ClaimCenterClient cc;
  public FNOLOrchestrator(InputGuardrail input,OutputGuardrail output,PIIGuardrail piiGuard,ValidationGuardrail validation,VisionDamageAgent vision,PolicyValidatorAgent policy,ReserveCalculatorAgent reserve,PiiRedactionAgent pii,StatutoryDeadlineAgent deadline,SubrogationScorerAgent subro,AuditTrailAgent audit,ClaimCenterClient cc){this.input=input;this.output=output;this.piiGuard=piiGuard;this.validation=validation;this.vision=vision;this.policy=policy;this.reserve=reserve;this.pii=pii;this.deadline=deadline;this.subro=subro;this.audit=audit;this.cc=cc;}
  public FNOLResponse process(FNOLPayload p){ input.validate(p); var damage=vision.execute(p); var coverage=policy.execute(p.policyNumber()); validation.requireCovered(coverage); var res=reserve.execute(damage); var piiResult=pii.execute(p); piiGuard.validate(piiResult); var deadlineResult=deadline.execute(p); var sub=subro.execute(p,damage); output.validate(res,sub); var created=cc.createClaim(new ClaimCreateRequest(p.policyNumber(),p.incidentDate(),p.state(),damage.estimatedDamage(),res.recommendedReserve())); var records=List.of(audit.record(created.claimId(),"VisionDamageAgent",p,damage,"SUCCESS"),audit.record(created.claimId(),"PolicyValidatorAgent",p.policyNumber(),coverage,"SUCCESS"),audit.record(created.claimId(),"ReserveCalculatorAgent",damage,res,"SUCCESS"),audit.record(created.claimId(),"ComplianceAgents",piiResult,sub,"SUCCESS")); return new FNOLResponse(created.claimId(),created.status(),new BranchAResult(damage,coverage,res),new BranchBResult(piiResult,deadlineResult,sub,records),List.of("AI-assisted decision support only; human claim handlers retain final decision authority.","Coverage recommendation is based on Mock PolicyCenter contracts and synthetic Sprint 2 rules.","Reserve equals estimated visual damage multiplied by 1.15.","Subrogation score is deterministic and explained by contributing factors.")); }
}
